"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[4791],{98567(e,i,a){a.r(i),a.d(i,{assets:()=>l,contentTitle:()=>u,default:()=>d,frontMatter:()=>c,metadata:()=>t,toc:()=>s});const t=JSON.parse('{"id":"learning/courses/quantum-computing-in-practice/applications-of-qc","title":"Pentru ce tipuri de probleme sunt bune calculatoarele cuantice?","description":"Cite\u0219te despre cum decidem ce tipuri de probleme ar putea beneficia de o solu\u021bie cuantic\u0103 \u0219i prive\u0219te c\xe2teva exemple recente de lucr\u0103ri ale comunit\u0103\u021bii.","source":"@site/i18n/ro/docusaurus-plugin-content-docs/current/learning/courses/quantum-computing-in-practice/applications-of-qc.mdx","sourceDirName":"learning/courses/quantum-computing-in-practice","slug":"/learning/courses/quantum-computing-in-practice/applications-of-qc","permalink":"/learning/courses/quantum-computing-in-practice/applications-of-qc","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/quantum-computing-in-practice/applications-of-qc.mdx","tags":[],"version":"current","frontMatter":{"title":"Pentru ce tipuri de probleme sunt bune calculatoarele cuantice?","sidebar_label":"Pentru ce tipuri de probleme sunt bune calculatoarele cuantice?","description":"Cite\u0219te despre cum decidem ce tipuri de probleme ar putea beneficia de o solu\u021bie cuantic\u0103 \u0219i prive\u0219te c\xe2teva exemple recente de lucr\u0103ri ale comunit\u0103\u021bii.","notebook_path":"learning/courses/quantum-computing-in-practice/applications-of-qc.ipynb"},"sidebar":"tutorialsSidebar","previous":{"title":"Utility-scale QAOA","permalink":"/learning/courses/quantum-computing-in-practice/utility-scale-qaoa"},"next":{"title":"Mapare","permalink":"/learning/courses/quantum-computing-in-practice/mapping"}}');var r=a(74848),n=a(28453);const c={title:"Pentru ce tipuri de probleme sunt bune calculatoarele cuantice?",sidebar_label:"Pentru ce tipuri de probleme sunt bune calculatoarele cuantice?",description:"Cite\u0219te despre cum decidem ce tipuri de probleme ar putea beneficia de o solu\u021bie cuantic\u0103 \u0219i prive\u0219te c\xe2teva exemple recente de lucr\u0103ri ale comunit\u0103\u021bii.",notebook_path:"learning/courses/quantum-computing-in-practice/applications-of-qc.ipynb"},u=void 0,l={},s=[{value:"Introducere",id:"introduction",level:2},{value:"Dificultate clasic\u0103 vs. cuantic\u0103",id:"classical-vs-quantum-difficulty",level:2},{value:"Clase de complexitate",id:"complexity-classes",level:3},{value:"Calculatoarele cuantice de ast\u0103zi \u0219i limitele lor",id:"todays-quantum-computers-and-their-limits",level:3},{value:"Domenii de aplicare \u0219i cazuri de utilizare",id:"application-areas-and-use-cases",level:2},{value:"Cazul de utilizare 1: Simularea dinamicii hadroanelor",id:"use-case-1-simulating-hadron-dynamics",level:3},{value:"Cazul de utilizare 2: Optimizarea unui spin-glass Ising",id:"use-case-2-optimization-of-an-ising-spin-glass",level:3},{value:"Cazul de utilizare 3: predic\u021bia structurii secundare a ARNm",id:"use-case-3-mrna-secondary-structure-prediction",level:3},{value:"Concluzie",id:"conclusion",level:2}];function o(e){const i={a:"a",annotation:"annotation",h2:"h2",h3:"h3",img:"img",li:"li",math:"math",mi:"mi",mn:"mn",mo:"mo",mrow:"mrow",ol:"ol",p:"p",semantics:"semantics",span:"span",ul:"ul",...(0,n.R)(),...e.components},{IBMVideo:t}=i;return t||function(e,i){throw new Error("Expected "+(i?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("IBMVideo",!0),(0,r.jsxs)(r.Fragment,{children:["\n","\n",(0,r.jsxs)(i.p,{children:["Urm\u0103re\u0219te videoclipul despre aplica\u021biile calculului cuantic realizat de Olivia Lanes sau deschide videoclipul \xeentr-o fereastr\u0103 separat\u0103 pe ",(0,r.jsx)(i.a,{href:"https://youtu.be/33QmsXhIlpU",children:"YouTube."})]}),"\n",(0,r.jsx)(t,{id:"134063426",title:"\xcen acest videoclip, Olivia Lanes descrie c\xe2teva aplica\u021bii posibile ale calculului cuantic la scar\u0103 utilitar\u0103. Acestea includ simularea hadronilor \u0219i a sticlelor de spin, precum \u0219i modelarea structurii proteinelor."}),"\n",(0,r.jsx)(i.h2,{id:"introduction",children:"Introducere"}),"\n",(0,r.jsx)(i.p,{children:"\xcen lec\u021bia anterioar\u0103, am abordat \xeen profunzime o singur\u0103 problem\u0103 \u2013 rezolvarea problemei de optimizare Max-Cut folosind formularea QUBO. Ast\u0103zi vom adopta o abordare diferit\u0103 \u0219i vom discuta aplica\u021biile pe termen scurt \xeentr-un mod mai larg. Vom \xeencepe prin a-\u021bi oferi o idee despre cum decidem ce tipuri de probleme credem c\u0103 ar putea beneficia de o solu\u021bie cuantic\u0103. Apoi, vom examina c\xe2teva exemple recente de lucr\u0103ri realizate \xeen comunitatea noastr\u0103. Aceasta te va ajuta s\u0103 \xee\u021bi dezvol\u021bi o intui\u021bie pentru diferitele tipuri de probleme de calcul cuantic \u0219i modul \xeen care le abord\u0103m."}),"\n",(0,r.jsx)(i.h2,{id:"classical-vs-quantum-difficulty",children:"Dificultate clasic\u0103 vs. cuantic\u0103"}),"\n",(0,r.jsx)(i.p,{children:"\xcenainte de a trece la exemple, s\u0103 discut\u0103m mai \xeent\xe2i despre cum studiem \u0219i clasific\u0103m dificultatea diverselor probleme. Unele probleme pot fi rezolvate u\u0219or pe un calculator clasic \u0219i nu avem nevoie de un calculator cuantic pentru a le rezolva. Pe de alt\u0103 parte, exist\u0103 probleme foarte dificile pentru care calculatoarele cuantice sunt necesare. Un exemplu celebru este g\u0103sirea factorilor primi ai unor numere \xeentregi enorme. Criptarea RSA se bazeaz\u0103 pe dificultatea acestei probleme, iar algoritmul lui Shor a fost conceput pentru a o rezolva pe un calculator cuantic. Un alt exemplu este g\u0103sirea unei solu\u021bii \xeentr-un set de date nesortate \u2013 aceasta poate fi teoretic rezolvat\u0103 de algoritmul cuantic cunoscut drept algoritmul lui Grover. Cu toate acestea, majoritatea exper\u021bilor sunt de acord c\u0103 aceste tipuri de algoritmi vor necesita implementarea corec\u021biei erorilor, iar tehnologia nu a ajuns \xeenc\u0103 acolo."}),"\n",(0,r.jsx)(i.p,{children:"Prin urmare, c\u0103ut\u0103m probleme pe care le putem aborda undeva \xeentr-o zon\u0103 de echilibru \xeentre cele foarte u\u0219oare \u0219i cele foarte dificile \u2013 unele pe care calculatoarele cuantice de ast\u0103zi le pot aborda, dar cu care calculatoarele clasice au dificult\u0103\u021bi."}),"\n",(0,r.jsx)(i.h3,{id:"complexity-classes",children:"Clase de complexitate"}),"\n",(0,r.jsx)(i.p,{children:"Dificultatea acestor probleme este clasificat\u0103 \u0219i analizat\u0103 \xeentr-o ramur\u0103 a informaticii numit\u0103 teoria complexit\u0103\u021bii computa\u021bionale. Exist\u0103 o mul\u021bime de clase de complexitate diferite \xeen calculul clasic, dar unele dintre cele mai fundamentale sunt:"}),"\n",(0,r.jsxs)(i.ul,{children:["\n",(0,r.jsx)(i.li,{children:"P: Probleme care pot fi rezolvate \xeen timp polinomial pe m\u0103sur\u0103 ce scara problemei cre\u0219te. Sunt u\u0219or de rezolvat."}),"\n",(0,r.jsx)(i.li,{children:"NP: Aceasta \xeenseamn\u0103 polinomial nedeterminist. Aceste probleme nu pot fi neap\u0103rat rezolvate \xeen timp polinomial, dar r\u0103spunsurile lor pot fi verificate \xeen timp polinomial."}),"\n",(0,r.jsx)(i.li,{children:"NP-complete sunt cele mai dificile probleme din NP \u0219i nu au nicio solu\u021bie polinomial\u0103 cunoscut\u0103. Aici tr\u0103iesc probleme celebre precum problema comisului voiajor \u0219i jocul Sudoku."}),"\n",(0,r.jsx)(i.li,{children:"BPP, sau probleme polinomiale cu eroare limitat\u0103, care pot fi rezolvate \xeentr-un prag de eroare de c\u0103tre un calculator clasic probabilistic \xeen timp polinomial."}),"\n"]}),"\n",(0,r.jsx)(i.p,{children:"C\xe2nd a fost inventat conceptul de calcul cuantic, oamenii au depus eforturi considerabile pentru a \xeen\u021belege ce clas\u0103 de probleme aceste noi tipuri de calculatoare vor putea rezolva eficient. A fost inventat\u0103 o nou\u0103 clas\u0103 de probleme:"}),"\n",(0,r.jsxs)(i.ul,{children:["\n",(0,r.jsx)(i.li,{children:"BQP, sau probleme cuantice polinomiale cu eroare limitat\u0103. Aceasta este echivalentul cuantic al BPP: este clasa de probleme de decizie rezolvabile de un calculator cuantic \xeen timp polinomial cu o \u0219ans\u0103 mic\u0103 de eroare."}),"\n"]}),"\n",(0,r.jsx)(i.p,{children:(0,r.jsx)(i.img,{alt:"Rela\u021bii suspectate \xeentre clasele de complexitate",src:a(52600).A+"",width:"976",height:"682"})}),"\n",(0,r.jsx)(i.p,{children:"Toate aceste clase tr\u0103iesc \xeentr-o clas\u0103 mai mare pe care o numim PSPACE. Mai sus se afl\u0103 o diagram\u0103 a rela\u021biilor suspectate \xeentre unele dintre clasele de complexitate, dar este foarte greu s\u0103 demonstrezi riguros acest lucru din punct de vedere matematic. Vei observa c\u0103 BQP nu se suprapune neap\u0103rat cu NP-complete. Dar este posibil s\u0103 fi v\u0103zut totu\u0219i unele abord\u0103ri de calcul cuantic care \xeencearc\u0103 s\u0103 rezolve probleme din NP-complete."}),"\n",(0,r.jsx)(i.p,{children:"O concep\u021bie gre\u0219it\u0103 comun\u0103 este c\u0103 nu are sens s\u0103 explorezi solu\u021bii cuantice pentru problemele \xeen care nu a fost g\u0103sit\u0103 o dovad\u0103 matematic\u0103 pentru o accelerare cuantic\u0103. Dar o dovad\u0103 matematic\u0103 c\u0103 un algoritm cuantic este mai rapid dec\xe2t omologul s\u0103u clasic este greu de g\u0103sit. Shor \u0219i Grover sunt dou\u0103 dintre pu\u021binele exemple \xeen care acest lucru a fost realizat p\xe2n\u0103 acum. De fapt, demonstrarea riguroas\u0103 c\u0103 P \u0219i NP sunt diferite este una dintre cele mai notorii probleme deschise din toat\u0103 matematica, chiar dac\u0103 toat\u0103 intui\u021bia ne spune c\u0103 trebuie s\u0103 fie diferite."}),"\n",(0,r.jsx)(i.p,{children:"Dar modul \xeen care un algoritm se scaleaz\u0103 cu cre\u0219terea dimensiunii problemei \u2013 ceea ce se reflect\u0103 \xeen clasa de complexitate \u2013 nu este \xeentotdeauna cea mai relevant\u0103 caracteristic\u0103 a unui algoritm. Aceast\u0103 scalare este adesea scenariul cel mai defavorabil. Este destul de posibil ca, \xeen practic\u0103, scenariul cel mai defavorabil s\u0103 nu fie cel cu care ne confrunt\u0103m cel mai des."}),"\n",(0,r.jsx)(i.p,{children:"Faptul c\u0103 dovezile de dificultate sunt complicate nu \xeenseamn\u0103 c\u0103 nu putem face progrese. Introducem ideea de solu\u021bii euristice. Dac\u0103 e\u0219ti un experimentalist, probabil c\u0103 cuno\u0219ti \u0219i \xee\u021bi plac aceste tipuri de solu\u021bii. O euristic\u0103 este orice abordare pragmatic\u0103, dar nu neap\u0103rat optim\u0103, a rezolv\u0103rii unei probleme, deoarece solu\u021biile nu trebuie s\u0103 fie optime pentru a fi utile. De exemplu, g\xe2nde\u0219te-te la aplica\u021biile financiare. Nu am g\u0103sit \xeenc\u0103 o accelerare exponen\u021bial\u0103 pentru majoritatea algoritmilor financiari \xeen care ar putea fi utilizat calculul cuantic, dar nu avem nevoie de o solu\u021bie optim\u0103. \xcen finan\u021be, chiar \u0219i o solu\u021bie cu 0,1% mai eficient\u0103 ar putea echivala cu miliarde de dolari de profit."}),"\n",(0,r.jsx)(i.h3,{id:"todays-quantum-computers-and-their-limits",children:"Calculatoarele cuantice de ast\u0103zi \u0219i limitele lor"}),"\n",(0,r.jsx)(i.p,{children:"Deci, cum \u0219tim ce cazuri de utilizare \u0219i probleme ar putea fi potrivite pentru calculul cuantic \xeen prezent? Exist\u0103 un motiv \xeentemeiat s\u0103 credem c\u0103 utilitatea cuantic\u0103, sau chiar avantajul cuantic, poate fi g\u0103sit fie acum, fie \xeen viitorul apropiat?"}),"\n",(0,r.jsx)(i.p,{children:"Poate c\u0103 este mai u\u0219or s\u0103 numim mai \xeent\xe2i lucrurile pe care problema cu siguran\u021b\u0103 nu ar trebui s\u0103 le aib\u0103. Nu poate necesita un num\u0103r enorm de qubi\u021bi. Nu avem \xeenc\u0103 procesoare cu mii p\xe2n\u0103 la milioane de qubi\u021bi disponibili. Acesta este unul dintre principalele motive pentru care algoritmul lui Shor \u0219i cei similari sunt at\xe2t de departe de a fi realiza\u021bi. Circuitele nu pot fi nici prea ad\xe2nci. Limita ad\xe2ncimii circuitului depinde de mul\u021bi factori, dar \xeen general, dac\u0103 experimentul t\u0103u necesit\u0103 o ad\xe2ncime pe care nu ai v\u0103zut-o realizat\u0103 \xeen literatura de specialitate, probabil c\u0103 nu va func\u021biona. \u0218i \xeen cele din urm\u0103, niciun tip de algoritm despre care \u0219tim c\u0103 va necesita corec\u021bia erorilor nu poate fi realizat \xeenc\u0103."}),"\n",(0,r.jsxs)(i.p,{children:["Toate aceste limit\u0103ri sunt abordate \xeen ",(0,r.jsx)(i.a,{href:"https://www.ibm.com/quantum/technology#roadmap",children:"foaia de parcurs IBM Quantum\xae"})," \u0219i ne a\u0219tept\u0103m s\u0103 realiz\u0103m corec\u021bia erorilor la \xeenceputul anilor 2030, dar deocamdat\u0103 trebuie s\u0103 c\u0103ut\u0103m experimente care s\u0103 fac\u0103 uz de c\xe2t mai mul\u021bi qubi\u021bi disponibili \xeen prezent pe un QPU dat. Subliniem, de asemenea, importan\u021ba atenu\u0103rii \u0219i suprim\u0103rii erorilor. \u0218i \xeen cele din urm\u0103, ar trebui s\u0103 existe o extensie evident\u0103 la aplica\u021bii viitoare care ar fi importante pentru societate \u0219i care ar putea duce \xeen cele din urm\u0103 la avantaj cuantic."]}),"\n",(0,r.jsx)(i.h2,{id:"application-areas-and-use-cases",children:"Domenii de aplicare \u0219i cazuri de utilizare"}),"\n",(0,r.jsx)(i.p,{children:"S\u0103 vorbim acum despre c\xe2teva exemple de cazuri de utilizare, care se \xeencadreaz\u0103 \xeen trei categorii principale pe care le-am identificat ca cele mai susceptibile de a vedea rezultate favorabile pe termen scurt p\xe2n\u0103 la mediu:"}),"\n",(0,r.jsxs)(i.ol,{children:["\n",(0,r.jsxs)(i.li,{children:["\n",(0,r.jsxs)(i.p,{children:["Simul\u0103ri ale naturii. Metodele clasice actuale de simulare atomic\u0103 \u0219i molecular\u0103 sunt limitate de descrierile matematice ineficiente ale structurii atomice. Stocarea \u0219i manipularea unei st\u0103ri cuantice necesit\u0103 resurse exponen\u021bial mai mari pe un calculator clasic, dar poate fi realizat\u0103 eficient pe un calculator cuantic. Aceasta ar putea duce la dezvolt\u0103ri \xeen sechestrarea dioxidului de carbon, baterii alternative sau inventarea de noi medicamente. C\xe2\u021biva algoritmi deosebit de relevan\u021bi \xeen aceast\u0103 zon\u0103 sunt: Variational Quantum Eigensolver (VQE), care este utilizat pentru a estima anumite propriet\u0103\u021bi ale unui material, cum ar fi st\u0103rile de echilibru sau energie minim\u0103; algoritmul Time Dynamics Simulation (TDS), care este utilizat pentru a estima func\u021biile de r\u0103spuns sau propriet\u0103\u021bile spectrale ale materialelor; \u0219i un nou venit, ",(0,r.jsx)(i.a,{href:"/learning/courses/quantum-diagonalization-algorithms/sqd-overview",children:"Sample-based Quantum Diagonalization (SQD)"}),", despre care credem c\u0103 vom auzi mult mai mult \xeen viitorul apropiat."]}),"\n"]}),"\n",(0,r.jsxs)(i.li,{children:["\n",(0,r.jsx)(i.p,{children:"Optimizare. Aceast\u0103 zon\u0103 este ubiquitar\u0103 \xeen calcul, deci cazurile de utilizare sunt numeroase \u0219i variate. C\xe2teva exemple despre care auzim mult sunt optimizarea portofoliului \xeen finan\u021be, proiectarea industrial\u0103 \u0219i distribu\u021bia \u0219i lan\u021bul de aprovizionare. Cel mai comun algoritm pe care \xeel vei auzi probabil \xeen leg\u0103tur\u0103 cu finan\u021bele este cel pe care l-am abordat deja \xeen profunzime: algoritmul cuantic de optimizare aproximativ\u0103, sau QAOA."}),"\n"]}),"\n",(0,r.jsxs)(i.li,{children:["\n",(0,r.jsx)(i.p,{children:"\xcenv\u0103\u021bare automat\u0103 cuantic\u0103. Aceast\u0103 zon\u0103 a generat mult\u0103 entuziasm \xeen ultimii c\xe2\u021biva ani, dar este probabil c\u0103 QML nu va fi util\u0103 la fel de cur\xe2nd ca simularea. Exist\u0103 totu\u0219i c\xe2\u021biva algoritmi impresionanti care sunt dezvolta\u021bi pentru a aborda c\xe2teva cazuri de utilizare foarte importante. Unele dintre aceste posibile cazuri de utilizare sunt procesarea limbajului natural, analiza traficului de re\u021bea \u0219i chiar detectarea fraudelor \xeen tranzac\u021biile financiare. Algoritmii relevan\u021bi \xeen aceast\u0103 zon\u0103 sunt ma\u0219ina cuantic\u0103 cu vector suport (QSVM), re\u021belele neuronale cuantice (QNN) \u0219i re\u021belele adversariale generative cuantice."}),"\n"]}),"\n"]}),"\n",(0,r.jsx)(i.p,{children:"\xcen cadrul acestor domenii largi de aplicare, comunitatea vede beneficiul \xeen grupurile care lucreaz\u0103 \xeempreun\u0103 \u0219i care sunt concentrate pe un subiect mai specific. IBM\xae a ini\u021biat o ini\u021biativ\u0103 numit\u0103 Grupuri de Lucru pentru a ajuta colaboratorii s\u0103 se cunoasc\u0103 \u0219i s\u0103 creeze sinergie productiv\u0103 \xeen patru domenii specifice: s\u0103n\u0103tate \u0219i \u0219tiin\u021be ale vie\u021bii, materiale \u0219i calcul de \xeenalt\u0103 performan\u021b\u0103 (HPC), fizica energiilor \xeenalte \u0219i optimizare. \u0218i recent, a fost creat un al cincilea grup de lucru privind sustenabilitatea."}),"\n",(0,r.jsx)(i.p,{children:"Acum vom examina mai \xeendeaproape c\xe2teva probleme care au fost recent abordate de unele dintre aceste grupuri de lucru. Scopul principal aici nu este s\u0103 \xeen\u021belegi fiecare detaliu al unui experiment \u2013 acest lucru poate fi intimidant chiar \u0219i pentru exper\u021bi dac\u0103 lucrarea este u\u0219or \xeen afara domeniului t\u0103u de expertiz\u0103. Scopul este pur \u0219i simplu de a ajuta la dezvoltarea unei intui\u021bii pentru tipurile de probleme pentru care calculatoarele cuantice sunt potrivite \u0219i cum s\u0103 le abordezi. \u0218i dac\u0103 e\u0219ti interesat, te \xeencuraj\u0103m s\u0103 cite\u0219ti lucr\u0103rile complete."}),"\n",(0,r.jsx)(i.h3,{id:"use-case-1-simulating-hadron-dynamics",children:"Cazul de utilizare 1: Simularea dinamicii hadroanelor"}),"\n",(0,r.jsxs)(i.p,{children:["Mai \xeent\xe2i, vom analiza un articol al grupului lui Martin Savage de la Universitatea din Washington, intitulat ",(0,r.jsx)(i.a,{href:"https://journals.aps.org/prd/abstract/10.1103/PhysRevD.109.114510",children:"Quantum Simulations of Hadron Dynamics in the Schwinger Model Using 112 Qubits"}),"."]}),"\n",(0,r.jsx)(i.p,{children:'Dac\u0103 nu e\u0219ti fizician de \xeenalt\u0103 energie, s-ar putea totu\u0219i s\u0103 fii familiarizat cu termenul \u201ehadron", ca \xeen Marele Accelerator de Hadroni (LHC) \u2014 acel accelerator de particule uria\u0219, cu o circumferin\u021b\u0103 de 27 km, care a f\u0103cut posibil\u0103 observarea \xeen final a bosonului Higgs. Un hadron este o particul\u0103 subatomic\u0103 compus\u0103 din alte particule mici numite quarci. C\xe2teva exemple de hadroane sunt neutronii \u0219i protonii.'}),"\n",(0,r.jsx)(i.p,{children:"Pentru pu\u021bin context: LHC a fost construit pentru a permite studiul fizicii fundamentale prin coliziunea particulelor la energii extrem de mari. Cu ajutorul LHC, oamenii de \u0219tiin\u021b\u0103 sper\u0103 s\u0103 afle mai multe despre universul timpuriu \u0219i legile fundamentale ale naturii. \xcen principiu, interac\u021biunile acestor particule ar putea fi simulate de la \xeenceput p\xe2n\u0103 la sf\xe2r\u0219it cu un calculator cuantic suficient de puternic. Nu am ajuns \xeenc\u0103 acolo, dar facem progrese."}),"\n",(0,r.jsx)(i.p,{children:"Modelul Schwinger este un model simplu \u0219i popular, folosit pentru a simula o parte din aceste dinamici. Este un model care descrie comportamentul electronilor \u0219i pozitronilor ce interac\u021bioneaz\u0103 prin fotoni \xeen 1+1D, adic\u0103 timp \u0219i o dimensiune spa\u021bial\u0103. Modelul are multe similarit\u0103\u021bi cu cromodinamica cuantic\u0103 (QCD), care descrie modul \xeen care quarcii \u0219i hadroanele interac\u021bioneaz\u0103, \xeens\u0103 QCD este extrem de greu de simulat. Prin urmare, modelul Schwinger este adesea utilizat ca model de juc\u0103rie pentru a investiga unele fenomene comune ambelor."}),"\n",(0,r.jsx)(i.p,{children:"Pentru a \xeen\u021belege de ce au abordat aceast\u0103 problem\u0103, hai s\u0103 ne punem o serie de \xeentreb\u0103ri."}),"\n",(0,r.jsx)(i.p,{children:"\xcen primul r\xe2nd, de ce aveau motive s\u0103 cread\u0103 c\u0103 simularea acestui lucru pe un calculator cuantic ar func\u021biona deloc? \xcen acest caz, electronii \u0219i pozitronii din modelul Schwinger au un efect de ecranare, determin\xe2nd corela\u021biile dintre fermionii \xeendep\u0103rta\u021bi s\u0103 scad\u0103 exponen\u021bial cu distan\u021ba. Asta \xeenseamn\u0103 c\u0103 nu sunt necesare at\xe2t de multe interac\u021biuni pe distan\u021be lungi de la un Qubit de pe o parte a cipului la altul \u2014 \u0219tim c\u0103 acestea sunt foarte predispuse la erori. Deci, e excelent pentru hardware-ul disponibil ast\u0103zi."}),"\n",(0,r.jsx)(i.p,{children:"Apoi, de ce este acest subiect de interes? Fizica de \xeenalt\u0103 energie \xeen general prezint\u0103 un interes deosebit. Oamenii au fost dispu\u0219i s\u0103 cheltuiasc\u0103 miliarde de dolari pentru a construi LHC, iar mul\u021bi mii de oameni de \u0219tiin\u021b\u0103 \u0219i tehnicieni din \xeentreaga lume \u0219i-au dedicat cariera acestui domeniu. De\u0219i modelul Schwinger este simplificat \u0219i nu este conceput s\u0103 acopere trei dimensiuni spa\u021biale, r\u0103m\xe2ne totu\u0219i o simplificare util\u0103 a teoriei complete."}),"\n",(0,r.jsx)(i.p,{children:"\xcen sf\xe2r\u0219it, cum a fost realizat\u0103 aceast\u0103 munc\u0103 sau cum am aborda problema dac\u0103 am dori s\u0103 continu\u0103m aceast\u0103 cercetare? \xcen experimentele de tip simulare, VQE este una dintre cele mai comune abord\u0103ri, iar primul pas este aproape \xeentotdeauna acela\u0219i: preg\u0103tirea st\u0103rii fundamentale. \xcen acest caz, este o stare de vid. \xcen acest experiment, se folose\u0219te o nou\u0103 versiune de VQE numit\u0103 SC-ADAPT-VQE (care \xeenseamn\u0103 Scalable Circuits - Adaptive Derivative-Assembled Pseudo-Trotter ansatz-VQE) pentru a preg\u0103ti at\xe2t starea fundamental\u0103, c\xe2t \u0219i pachetul de und\u0103 al hadronului pe acest vid. Pasul urm\u0103tor este s\u0103 l\u0103s\u0103m hadroanele s\u0103 evolueze \xeen timp. \xcen final, identific\u0103m observabilele pe care dorim s\u0103 le m\u0103sur\u0103m \u0219i le m\u0103sur\u0103m."}),"\n",(0,r.jsx)(i.p,{children:"Dac\u0103 ace\u0219ti pa\u0219i \u021bi se par oarecum familiari \u2014 cu excep\u021bia p\u0103r\u021bii cu pachetul de und\u0103 al hadronului \u2014, e pentru c\u0103 sunt foarte similari cu ceea ce am acoperit \xeen exemplul QAOA din lec\u021bia anterioar\u0103. \xcencepem dintr-o stare familiar\u0103 (aici starea de vid), \u0219i apoi l\u0103s\u0103m sistemul s\u0103 evolueze \xeen timp printr-o serie de hamiltoniene exponen\u021biate. Multe algoritmi varia\u021bionali urmeaz\u0103 aceast\u0103 abordare general\u0103. O diferen\u021b\u0103 important\u0103 aici, \xeens\u0103, este c\u0103 cre\u0103m pachetul de und\u0103 al hadronilor centrat \xeen circuitul nostru, \xeenainte de a \xeencepe s\u0103-l l\u0103s\u0103m s\u0103 evolueze."}),"\n",(0,r.jsx)(i.p,{children:"Deci, cum cre\u0103m pachetul de und\u0103? Pe vid, un hadron poate fi excitat prin crearea unei perechi fermion-antifermion pe situri adiacente. Preg\u0103tind o suprapunere a unor astfel de hadroane \xeen loca\u021bii diferite, se poate preg\u0103ti un pachet de und\u0103 arbitrar. Autorii \u0219i-au centrat pachetul de und\u0103 \xeen mijlocul circuitului pentru a observa evolu\u021bia f\u0103r\u0103 a atinge o grani\u021b\u0103."}),"\n",(0,r.jsx)(i.p,{children:"Dar \u021bine minte: numele jocului atunci c\xe2nd lucrezi cu QPU-uri zgomotoase este s\u0103 men\u021bii ad\xe2ncimea circuitului la un nivel gestionabil. Pentru a face asta, protocolul SC-ADAPT-VQE folose\u0219te simetrii \u0219i ierarhii \xeen sc\u0103rile de lungime pentru a determina circuite cuantice de mic\u0103 ad\xe2ncime pentru preg\u0103tirea st\u0103rilor. Acest lucru va crea un ansatz cu un num\u0103r mai mic de parametri \u0219i, prin urmare, o ad\xe2ncime mai mic\u0103."}),"\n",(0,r.jsx)(i.p,{children:"Experimentul a fost rulat pe un dispozitiv IBM Quantum Heron \u0219i a inclus c\xe2teva tipuri diferite de atenuare \u0219i suprimare a erorilor: decuplare dinamic\u0103, extrapolare la zgomot zero, r\u0103sucire Pauli \u0219i o tehnic\u0103 dezvoltat\u0103 recent numit\u0103 renormalizarea decoheren\u021bei operatorului."}),"\n",(0,r.jsx)(i.p,{children:(0,r.jsx)(i.img,{alt:"Rezultatele simul\u0103rilor de hadroane",src:a(77894).A+"",width:"1158",height:"838"})}),"\n",(0,r.jsx)(i.p,{children:"Mai sus este o figur\u0103 din articol care arat\u0103 observabilul de interes, condensatul chiral, care este practic o faz\u0103 de superfluid a hadronilor. Acum putem vedea pachetul de und\u0103 \xeen centrul siturilor desemnate pentru rularea acestui experiment. Liniile negre sunt rezultatele f\u0103r\u0103 erori din simularea clasic\u0103 (costisitoare din punct de vedere computa\u021bional), \xeen timp ce punctele cu bare de eroare sunt rezultatele de pe calculatorul cuantic IBM cu 133 de qubi\u021bi, Torino."}),"\n",(0,r.jsxs)(i.p,{children:["Vedem dou\u0103 etape de timp diferite \xeen evolu\u021bia pachetului de und\u0103. La timpul ",(0,r.jsxs)(i.span,{className:"katex",children:[(0,r.jsx)(i.span,{className:"katex-mathml",children:(0,r.jsx)(i.math,{xmlns:"http://www.w3.org/1998/Math/MathML",children:(0,r.jsxs)(i.semantics,{children:[(0,r.jsxs)(i.mrow,{children:[(0,r.jsx)(i.mi,{children:"t"}),(0,r.jsx)(i.mo,{children:"="}),(0,r.jsx)(i.mn,{children:"1"})]}),(0,r.jsx)(i.annotation,{encoding:"application/x-tex",children:"t=1"})]})})}),(0,r.jsxs)(i.span,{className:"katex-html","aria-hidden":"true",children:[(0,r.jsxs)(i.span,{className:"base",children:[(0,r.jsx)(i.span,{className:"strut",style:{height:"0.6151em"}}),(0,r.jsx)(i.span,{className:"mord mathnormal",children:"t"}),(0,r.jsx)(i.span,{className:"mspace",style:{marginRight:"0.2778em"}}),(0,r.jsx)(i.span,{className:"mrel",children:"="}),(0,r.jsx)(i.span,{className:"mspace",style:{marginRight:"0.2778em"}})]}),(0,r.jsxs)(i.span,{className:"base",children:[(0,r.jsx)(i.span,{className:"strut",style:{height:"0.6444em"}}),(0,r.jsx)(i.span,{className:"mord",children:"1"})]})]})]}),", po\u021bi vedea c\u0103 condensatul chiral este \xeengust \u0219i localizat, \u0219i se potrive\u0219te bine cu simularea clasic\u0103. La ",(0,r.jsxs)(i.span,{className:"katex",children:[(0,r.jsx)(i.span,{className:"katex-mathml",children:(0,r.jsx)(i.math,{xmlns:"http://www.w3.org/1998/Math/MathML",children:(0,r.jsxs)(i.semantics,{children:[(0,r.jsxs)(i.mrow,{children:[(0,r.jsx)(i.mi,{children:"t"}),(0,r.jsx)(i.mo,{children:"="}),(0,r.jsx)(i.mn,{children:"14"})]}),(0,r.jsx)(i.annotation,{encoding:"application/x-tex",children:"t=14"})]})})}),(0,r.jsxs)(i.span,{className:"katex-html","aria-hidden":"true",children:[(0,r.jsxs)(i.span,{className:"base",children:[(0,r.jsx)(i.span,{className:"strut",style:{height:"0.6151em"}}),(0,r.jsx)(i.span,{className:"mord mathnormal",children:"t"}),(0,r.jsx)(i.span,{className:"mspace",style:{marginRight:"0.2778em"}}),(0,r.jsx)(i.span,{className:"mrel",children:"="}),(0,r.jsx)(i.span,{className:"mspace",style:{marginRight:"0.2778em"}})]}),(0,r.jsxs)(i.span,{className:"base",children:[(0,r.jsx)(i.span,{className:"strut",style:{height:"0.6444em"}}),(0,r.jsx)(i.span,{className:"mord",children:"14"})]})]})]}),", este mult mai r\u0103sp\xe2ndit. Compara\u021bia cu simulatorul nu mai este la fel de perfect\u0103 acum, dar po\u021bi vedea totu\u0219i \xeen mod evident un acord foarte bun \xeentre teorie \u0219i date, ceea ce este \xeencurajator."]}),"\n",(0,r.jsx)(i.p,{children:"\xcen concluzie, acesta este un exemplu foarte interesant al tipului de munc\u0103 de simulare la care poate nu te-ai g\xe2ndi ini\u021bial s\u0103 aplici calculul cuantic, dar care arat\u0103 o promisiune real\u0103. Nu este perfect, dar nu trebuie s\u0103 fii expert \xeen fizica particulelor pentru a vedea c\u0103 calculatorul cuantic prezice cu acurate\u021be propagarea spre exterior a pachetului de und\u0103, ceea ce este exact ce ne-am fi a\u0219teptat s\u0103 g\u0103sim. Sper\u0103m c\u0103 lucr\u0103rile viitoare \xeen acest domeniu vor continua \u0219i c\u0103 fizicienii de \xeenalt\u0103 energie vor g\u0103si \xeen continuare modalit\u0103\u021bi de a incorpora calculul cuantic \xeen fluxurile lor de lucru. Scopul este de a rezolva probleme teoretice dificile mai precis \u0219i de a utiliza experimentele pentru a accepta sau respinge teorii, \xeen speran\u021ba descoperirii de fizic\u0103 nou\u0103, a construirii unor detectoare \xeembun\u0103t\u0103\u021bite \u0219i a unei mai bune \xeen\u021belegeri a naturii la nivelul ei cel mai fundamental."}),"\n",(0,r.jsx)(i.h3,{id:"use-case-2-optimization-of-an-ising-spin-glass",children:"Cazul de utilizare 2: Optimizarea unui spin-glass Ising"}),"\n",(0,r.jsxs)(i.p,{children:["Urm\u0103torul nostru exemplu se concentreaz\u0103 pe optimizare \u0219i va reprezenta o analiz\u0103 aprofundat\u0103 a unui articol numit ",(0,r.jsx)(i.a,{href:"https://arxiv.org/abs/2405.13898",children:"Bias-Field Digitized Counterdiabatic Quantum Optimization"}),", realizat de membrii echipei Kipu Quantum \u0219i ai Universit\u0103\u021bii din \u021aara Bascilor din Spania."]}),"\n",(0,r.jsx)(i.p,{children:'\xcen articol, autorii au dezvoltat o nou\u0103 metod\u0103 de optimizare \u0219i au aplicat-o pentru a g\u0103si starea fundamental\u0103 a unui spin-glass Ising. A\u0219a cum am discutat anterior, multe probleme de optimizare combinatorie pot fi reformulate ca rezolvare a st\u0103rilor de energie joas\u0103 ale Hamiltonienilor Ising. Modelul Ising descrie interac\u021biunea unui \u0219ir de spinuri microscopice. \xcen anumite regimuri, modelul prezice c\u0103 spinurile se comport\u0103 ca un sticl\u0103, \xeen care momentele magnetice sunt dezordonate deasupra unei a\u0219a-numite \u201etemperaturi de \xeenghe\u021b."'}),"\n",(0,r.jsx)(i.p,{children:"Vom \xeencepe, ca \u0219i \xeenainte, cu o serie de defini\u021bii. Prima este contradiabatic\u0103, adic\u0103 un tip de evolu\u021bie care suprim\u0103 efectele neadiabatice experimentate de un sistem, indiferent de c\xe2t de repede au loc acele procese. Reaminte\u0219te-\u021bi teorema adiabatic\u0103 din episodul anterior \u2014 de obicei trebuie s\u0103 eVoluezi un sistem foarte lent dac\u0103 dore\u0219ti ca acesta s\u0103 r\u0103m\xe2n\u0103 \xeen starea fundamental\u0103. Aceasta este o problem\u0103 major\u0103, deoarece cu c\xe2t trebuie s\u0103 evolu\u0103m mai lent lucrurile, cu at\xe2t avem mai mult timp pentru ca erorile s\u0103 apar\u0103. Conducerea contradiabatic\u0103 (CD) urm\u0103re\u0219te s\u0103 combat\u0103 acest lucru prin ad\u0103ugarea de termeni care contracareaz\u0103 aceste excita\u021bii nedorite. Ideea principal\u0103 este de a accelera \xeentregul experiment \u0219i de a reduce ad\xe2ncimea circuitului cuantic prin suprimarea excita\u021biilor care ar putea cauza tranzi\u021bii parazite."}),"\n",(0,r.jsx)(i.p,{children:"Acum pentru cealalt\u0103 terminologie din titlu: c\xe2mpul de polarizare. Al\u021bi algoritmi iterativi, precum VQE, introduc parametri clasici \xeen st\u0103ri \u0219i folosesc optimizatori clasici pentru a c\u0103uta \xeen spa\u021biul parametric multidimensional setul de parametri care produce o valoare de a\u0219teptare minim\u0103 pentru un Hamiltonian fix. \xcen acest caz, ei variaz\u0103 \xeen schimb Hamiltonianul de fiecare dat\u0103, deplas\xe2ndu-se adiabatic de la un caz cunoscut la cazul de interes. Pentru a schimba Hamiltonianul, ei aplic\u0103 pur \u0219i simplu valoarea de a\u0219teptare Pauli-Z dintr-o itera\u021bie ca un c\xe2mp de polarizare \xeen Hamiltonianul pentru itera\u021bia urm\u0103toare. \xcen acest fel, direc\u021bioneaz\u0103 dinamica spre solu\u021bia real\u0103 f\u0103r\u0103 a fi nevoie de optimizatori clasici."}),"\n",(0,r.jsx)(i.p,{children:"Deci, de ce prezint\u0103 interes acest experiment? Spin-glass-urile Ising sunt de interes fundamental \xeen fizic\u0103, dar aceast\u0103 nou\u0103 abordare este chiar mai general\u0103 dec\xe2t at\xe2t. Ar putea fi aplicat\u0103 multor probleme de optimizare, astfel c\u0103 articolul prezint\u0103 interes larg."}),"\n",(0,r.jsx)(i.p,{children:"\u0218i de ce am crezut c\u0103 va func\u021biona? Algoritmul pe care \xeel propun accelereaz\u0103 evolu\u021bia pentru a reduce ad\xe2ncimea circuitului, suprim\xe2nd totodat\u0103 tranzi\u021biile neadiabatice. Mai mult, nu se bazeaz\u0103 pe niciun subprogram de optimizare clasic, care poate fi o problem\u0103 ce duce la platouri sterile \u0219i la blocarea \xeen minime locale. \xcen cele din urm\u0103, autorii se asigur\u0103 c\u0103 aliniaz\u0103 interac\u021biunile din Hamiltonianul problemei cu conectivitatea hardware din QPU-urile reale, ceea ce este \xeentotdeauna foarte important."}),"\n",(0,r.jsx)(i.p,{children:"Deci, cum func\u021bioneaz\u0103 aceast\u0103 metod\u0103? Din nou, nu folose\u0219te niciun optimizator clasic, spre deosebire de majoritatea celorlal\u021bi algoritmi cuantici iterativi. \xcen schimb, prin furnizarea solu\u021biei din fiecare itera\u021bie ca intrare pentru urm\u0103toarea, algoritmul de optimizare cuantic\u0103 digitizat cu c\xe2mp de polarizare rafineaz\u0103 incremental starea fundamental\u0103, aduc\xe2nd-o din ce \xeen ce mai aproape de starea evoluat\u0103 final\u0103. \u0218i combinat cu protocoalele contradiabatice, putem face acest lucru chiar \u0219i cu circuite cuantice de ad\xe2ncime mic\u0103, care ar trebui s\u0103 ruleze f\u0103r\u0103 probleme pe hardware zgomotos."}),"\n",(0,r.jsx)(i.p,{children:"Astfel, c\xe2nd a fost realizat experimentul, autorii au ales s\u0103 ruleze algoritmul pe computerul cuantic IBM Quantum Brisbane de 127 de qubi\u021bi. Mai jos este o figur\u0103 care arat\u0103 cea de-a 8-a itera\u021bie a algoritmului de optimizare pentru o instan\u021b\u0103 de spin-glass generat\u0103 aleatoriu cu vecini apropia\u021bi pe 100 de qubi\u021bi. Ei compar\u0103 rezultatele de simulare clasic\u0103 idealizat\u0103 din DCQO \u0219i BF-DCQO, precum \u0219i rezultatul experimental rulat pe computerul cuantic. Arat\u0103, de asemenea, rezultatul unui solver clasic numit Gurobi ca referin\u021b\u0103. Cu doar 10 itera\u021bii, BF-DCQO ofer\u0103 o \xeembun\u0103t\u0103\u021bire drastic\u0103 fa\u021b\u0103 de DCQO. De\u0219i rezultatul experimental difer\u0103 pu\u021bin fa\u021b\u0103 de rezultatul ideal din cauza zgomotului, performan\u021ba este totu\u0219i mai bun\u0103 dec\xe2t DCQO ideal. Aceasta arat\u0103 c\u0103 exist\u0103 \xeen continuare progrese excelente \xeen ceea ce prive\u0219te optimizarea cuantic\u0103, iar rezultate bune sunt raportate pentru mai mult de 100 de qubi\u021bi pentru una dintre primele dat\u0103."}),"\n",(0,r.jsx)(i.p,{children:(0,r.jsx)(i.img,{alt:"Results from Ising spin-glass paper",src:a(43410).A+"",width:"976",height:"682"})}),"\n",(0,r.jsx)(i.h3,{id:"use-case-3-mrna-secondary-structure-prediction",children:"Cazul de utilizare 3: predic\u021bia structurii secundare a ARNm"}),"\n",(0,r.jsxs)(i.p,{children:["\xcen final, vom discuta un articol de la Moderna Pharmaceuticals intitulat ",(0,r.jsx)(i.a,{href:"https://arxiv.org/abs/2405.20328",children:"mRNA Secondary Structure Prediction Using Utility-Scale Quantum Computers"}),"."]}),"\n",(0,r.jsx)(i.p,{children:"Mai \xeent\xe2i, o scurt\u0103 recapitulare despre ARNm. ARN mesager este un tip de ARN implicat \xeen sinteza proteinelor. Practic, cite\u0219te instruc\u021biunile furnizate de ADN. Structura secundar\u0103 a ARNm reprezint\u0103 modul \xeen care lan\u021bul este pliat, a\u0219a cum se arat\u0103 \xeen diagrama de mai jos. Iar problema predic\u021biei structurii secundare a ARN este problema g\u0103sirii celui mai stabil pliat al secven\u021bei de baze sau nucleotide care alc\u0103tuiesc ARN-ul: adenina (A), citozina (C), uracilul (U) \u0219i guanina (G). Imaginea de mai jos arat\u0103 c\xe2teva structuri de pliere comune g\u0103site \xeen ARNm; fiecare culoare reprezint\u0103 un tip diferit de structur\u0103 secundar\u0103. Ce anume face o structur\u0103 mai favorabil\u0103 dec\xe2t celelalte nu este bine \xeen\u021beles; tot ce putem face este s\u0103 calcul\u0103m care structur\u0103 produce cea mai mic\u0103 energie liber\u0103 fa\u021b\u0103 de starea nepliat\u0103. \u0218i exact aici intervin calculatoarele cuantice."}),"\n",(0,r.jsx)(i.p,{children:(0,r.jsx)(i.img,{alt:"Diagrama structurii secundare a ARNm",src:a(41923).A+"",width:"638",height:"842"})}),"\n",(0,r.jsx)(i.p,{children:"Deci, de ce sunt importante structurile secundare ale ARNm? Predic\u021bia lor precis\u0103 este esen\u021bial\u0103 nu numai pentru \xeen\u021belegerea ADN-ului \u0219i a genelor noastre, ci \u0219i pentru proiectarea terapeuticelor bazate pe ARN, cum ar fi vaccinul COVID-19."}),"\n",(0,r.jsx)(i.p,{children:"Se \u0219tie de mult c\u0103 aceasta este o problem\u0103 de optimizare formidabil\u0103 pentru calculatoarele clasice, din cauza num\u0103rului vast de configura\u021bii posibile. Pentru unele configura\u021bii, se \u0219tie c\u0103 este o problem\u0103 NP-complet\u0103. Cu toate acestea, pe un calculator cuantic putem formula predic\u021bia structurii secundare ca o problem\u0103 de optimizare binar\u0103 \u2014 ceva ce \u0219tim cum s\u0103 gestion\u0103m. Mai mult, \xeen literatura de specialitate existau deja dovezi ale unor predic\u021bii ARN precise pe dispozitive cuantice la scar\u0103 mic\u0103 \u0219i pe simulatoare cuantice. Dar ar func\u021biona asta pe hardware mai mare?"}),"\n",(0,r.jsx)(i.p,{children:"Acest experiment a fost efectuat folosind ceva numit eigensolver cuantic varia\u021bional cu valoarea condi\u021bionat\u0103 la risc, care este o modificare a unui algoritm VQE tradi\u021bional \u0219i se a\u0219teapt\u0103 s\u0103 ob\u021bin\u0103 o convergen\u021b\u0103 mai bun\u0103."}),"\n",(0,r.jsx)(i.p,{children:(0,r.jsx)(i.img,{alt:"Rezultate din articolul despre ARNm",src:a(65188).A+"",width:"1158",height:"686"})}),"\n",(0,r.jsx)(i.p,{children:"Graficul de mai sus arat\u0103 distribu\u021bia probabilit\u0103\u021bilor de m\u0103surare ale \u0219irurilor de bi\u021bi e\u0219antionate, cu energiile corespunz\u0103toare pentru o instan\u021b\u0103 de 42 de nucleotide \u0219i 80 de qubi\u021bi. Aici, \u0219irurile de bi\u021bi simbolizeaz\u0103 \xeemperecherile de nucleotide. Ilustreaz\u0103 c\u0103 \u0219irul de bi\u021bi cu cea mai mic\u0103 energie g\u0103sit de calculatorul cuantic corespunde cu cel al solverului clasic comparativ, ceea ce este excelent. De asemenea, este prezentat\u0103 structura pliat\u0103 optim\u0103 a acelui lan\u021b nucleotidic, bazat\u0103 pe \u0219irul de bi\u021bi cu cea mai mic\u0103 energie g\u0103sit de calculatorul cuantic."}),"\n",(0,r.jsx)(i.h2,{id:"conclusion",children:"Concluzie"}),"\n",(0,r.jsx)(i.p,{children:"Sper\u0103m c\u0103 aceste trei cazuri de utilizare \u021bi-au oferit suficient context pentru a \xeen\u021belege cum arat\u0103 munca de ultim\u0103 or\u0103 din domeniu \xeen acest moment \u0219i \xeencrederea de a \xeencerca noi experimente cuantice pe care poate nu le-ai fi \xeencercat \xeenainte."}),"\n",(0,r.jsx)(i.p,{children:"\u021aine minte: calculul cuantic nu este potrivit pentru orice problem\u0103. \u0218i, de fapt, acesta este doar un testament al c\xe2t de buni am devenit la calculul clasic. Doar pentru c\u0103 crezi c\u0103 ai putea aplica calculul cuantic la o problem\u0103 nu \xeenseamn\u0103 c\u0103 va produce rezultate interesante; trebuie s\u0103 iei \xeen considerare scalarea."})]})}function d(e={}){const{wrapper:i}={...(0,n.R)(),...e.components};return i?(0,r.jsx)(i,{...e,children:(0,r.jsx)(o,{...e})}):o(e)}},52600(e,i,a){a.d(i,{A:()=>t});const t=a.p+"assets/images/complexity_classes-52979b588e98706373f7abc9b3f5f57c.avif"},77894(e,i,a){a.d(i,{A:()=>t});const t=a.p+"assets/images/hadron_paper-bc9c0a13fc3cd0e44b5c193902ce6dba.avif"},65188(e,i,a){a.d(i,{A:()=>t});const t=a.p+"assets/images/mrna_paper-4b1d694275f2539f69c49bfbb9b5ddd8.avif"},41923(e,i,a){a.d(i,{A:()=>t});const t=a.p+"assets/images/mrna_structure-962f2d5dfb98ac0a2e9c680e23d97ada.avif"},43410(e,i,a){a.d(i,{A:()=>t});const t=a.p+"assets/images/paper_results-aace6d8c4b97868e6cba7fc772e13ad9.avif"},28453(e,i,a){a.d(i,{R:()=>c,x:()=>u});var t=a(96540);const r={},n=t.createContext(r);function c(e){const i=t.useContext(n);return t.useMemo(function(){return"function"==typeof e?e(i):{...i,...e}},[i,e])}function u(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:c(e.components),t.createElement(n.Provider,{value:i},e.children)}}}]);